// Parses front matter, validates the caller's variables against the prompt's
// declared contract, interpolates, and returns the blob SHA so a later audit can
// prove exactly which prompt text produced a given model call.
const req = $('Normalise Prompt Request').first().json;
const res = $json || {};

const status = Number(res.statusCode || (res.error ? 0 : 200));
const bodyObj = res.body || res;

let vars = {};
let varsParseError = null;
try { vars = JSON.parse(req.variables || '{}'); }
catch (e) { varsParseError = 'variables is not valid JSON: ' + String(e.message || e); vars = {}; }

// ---- Bundled fallbacks ---------------------------------------------------
// A GitHub outage or rate limit must not take the whole platform down. These
// minimal copies keep the hot paths alive, clearly marked as degraded so a
// caller (and the audit log) can tell that the Git-tracked version was not used.
const FALLBACKS = {
  'verification/entailment-judge':
    'You are a strict entailment checker. Use ONLY the sources.\n\nSOURCES\n{{sources_block}}\n\nCLAIMS\n{{claims_block}}\n\n' +
    'Label each claim SUPPORTED, CONTRADICTED or NOT_STATED. A claim that is plausible but absent from the sources is NOT_STATED, never SUPPORTED.\n' +
    'Respond with raw JSON only: {"results":[{"n":1,"verdict":"SUPPORTED","source_id":"S1","evidence":"quote"}]}',
  'rag/answerer':
    'Answer the question using ONLY the context passages.\n\nQUESTION\n{{question}}\n\nCONTEXT\n{{context_block}}\n\n' +
    'Cite the passage marker such as [C2] after every sentence, at least {{min_citations}} distinct citations. ' +
    'If the context does not contain the answer reply exactly INSUFFICIENT_CONTEXT and name what is missing.'
};

function interpolate(body, values) {
  const used = [];
  const missing = [];
  const out = body.replace(/\{\{\s*([a-zA-Z_][a-zA-Z0-9_]*)\s*\}\}/g, function (m, name) {
    if (Object.prototype.hasOwnProperty.call(values, name) && values[name] !== null && values[name] !== undefined) {
      used.push(name);
      const v = values[name];
      return typeof v === 'string' ? v : JSON.stringify(v);
    }
    missing.push(name);
    return m;
  });
  return { text: out, used: used, missing: missing };
}

function parseFrontMatter(text) {
  if (!text.startsWith('---')) { return { meta: null, body: text, error: 'no front matter block' }; }
  const idx = text.indexOf('\n---', 3);
  if (idx === -1) { return { meta: null, body: text, error: 'front matter not closed' }; }
  const head = text.slice(3, idx).trim();
  const body = text.slice(idx + 4).replace(/^\n+/, '');
  const meta = {};
  head.split('\n').forEach(function (line) {
    const c = line.indexOf(':');
    if (c === -1) { return; }
    const k = line.slice(0, c).trim();
    const raw = line.slice(c + 1).trim();
    if (raw.startsWith('[') && raw.endsWith(']')) {
      const inner = raw.slice(1, -1).trim();
      meta[k] = inner ? inner.split(',').map(function (s) { return s.trim().replace(/^['"]|['"]$/g, ''); }) : [];
    } else if (/^-?\d+$/.test(raw)) {
      meta[k] = parseInt(raw, 10);
    } else {
      meta[k] = raw.replace(/^['"]|['"]$/g, '');
    }
  });
  return { meta: meta, body: body, error: null };
}

const issues = [];
if (varsParseError) { issues.push(varsParseError); }

let source = 'github';
let rawText = null;
let sha = null;
let degraded = false;

if (status === 200 && bodyObj && bodyObj.content) {
  rawText = Buffer.from(String(bodyObj.content).replace(/\n/g, ''), 'base64').toString('utf8');
  sha = bodyObj.sha || null;
} else {
  degraded = true;
  source = 'bundled_fallback';
  const httpMsg = status === 404
    ? 'prompt not found at ' + req.path + ' on ref ' + req.ref
    : (status === 403 ? 'GitHub rate limit or access denied (HTTP 403)' : 'GitHub fetch failed with HTTP ' + status);
  issues.push(httpMsg);
  if (FALLBACKS[req.prompt_id]) {
    rawText = '---\nid: ' + req.prompt_id + '\nversion: 0\ndescription: bundled fallback\nvariables: []\nowner: platform\nupdated: 1970-01-01\n---\n' + FALLBACKS[req.prompt_id];
    issues.push('served the bundled fallback copy of ' + req.prompt_id + '; this is NOT the Git-tracked version');
  } else {
    rawText = null;
    source = 'none';
  }
}

const latencyMs = req.started_at_ms ? (Date.now() - Number(req.started_at_ms)) : null;

if (rawText === null) {
  return {
    json: {
      ok: false, degraded: true, prompt_id: req.prompt_id, source: 'none',
      prompt: null, sha: null, version: null, ref: req.ref, path: req.path,
      missing_variables: [], unused_variables: [], issues: issues,
      source_workflow: req.source_workflow, latency_ms: latencyMs,
      provenance: req.owner + '/' + req.repo + '@' + req.ref + ':' + req.path + ' (unavailable)'
    }
  };
}

const fm = parseFrontMatter(rawText);
if (fm.error) { issues.push('front matter: ' + fm.error); }
const meta = fm.meta || {};
const declared = Array.isArray(meta.variables) ? meta.variables : [];

const rendered = interpolate(fm.body, vars);

// A variable the prompt declares but the caller did not supply is a contract
// breach. In strict mode it fails rather than shipping a prompt with a literal
// {{placeholder}} left in it, which models handle unpredictably.
const missingDeclared = declared.filter(function (d) { return !Object.prototype.hasOwnProperty.call(vars, d); });
const unusedSupplied = Object.keys(vars).filter(function (k) { return declared.indexOf(k) === -1; });
const missingAll = rendered.missing.filter(function (m, i, a) { return a.indexOf(m) === i; });

if (missingAll.length) { issues.push('unfilled placeholders: ' + missingAll.join(', ')); }
if (unusedSupplied.length) { issues.push('caller supplied variables the prompt does not declare: ' + unusedSupplied.join(', ')); }

const strictFail = req.strict === true && missingAll.length > 0;
const ok = !strictFail && !degraded ? true : (!strictFail && degraded ? true : false);

return {
  json: {
    ok: ok,
    degraded: degraded,
    prompt_id: req.prompt_id,
    source: source,
    prompt: strictFail ? null : rendered.text,
    sha: sha,
    version: typeof meta.version === 'number' ? meta.version : null,
    description: meta.description || null,
    owner_of_prompt: meta.owner || null,
    updated: meta.updated || null,
    ref: req.ref,
    path: req.path,
    declared_variables: declared,
    supplied_variables: Object.keys(vars),
    missing_variables: missingAll,
    unused_variables: unusedSupplied,
    strict: req.strict === true,
    issues: issues,
    source_workflow: req.source_workflow,
    latency_ms: latencyMs,
    provenance: req.owner + '/' + req.repo + '@' + req.ref + ':' + req.path + (sha ? ' blob ' + String(sha).slice(0, 12) : '')
  }
};

// Exercises the registry contract against the real GitHub repository.
const PLANNER_VARS = JSON.stringify({ question: 'What changed in EU battery regulation?', depth: 'standard', today: '2026-09-08' });
const F = [
  { case_id: 'P01-valid-render', prompt_id: 'research/planner', variables: PLANNER_VARS, ref: 'main', strict: 'true',
    expect_ok: true, expect_degraded: false, expect_source: 'github', expect_sha: true, expect_missing: [], expect_unused: [] },
  { case_id: 'P02-missing-variable-strict-fails', prompt_id: 'research/planner', variables: JSON.stringify({ question: 'x', today: '2026-09-08' }), ref: 'main', strict: 'true',
    expect_ok: false, expect_degraded: false, expect_source: 'github', expect_sha: true, expect_missing: ['depth'], expect_unused: [] },
  { case_id: 'P03-missing-variable-lenient-renders', prompt_id: 'research/planner', variables: JSON.stringify({ question: 'x', today: '2026-09-08' }), ref: 'main', strict: 'false',
    expect_ok: true, expect_degraded: false, expect_source: 'github', expect_sha: true, expect_missing: ['depth'], expect_unused: [] },
  { case_id: 'P04-unknown-prompt-id', prompt_id: 'research/does-not-exist', variables: '{}', ref: 'main', strict: 'true',
    expect_ok: false, expect_degraded: true, expect_source: 'none', expect_sha: false, expect_missing: [], expect_unused: [] },
  { case_id: 'P05-bad-ref-uses-bundled-fallback', prompt_id: 'verification/entailment-judge', variables: JSON.stringify({ sources_block: 'S1: text', claims_block: '1. claim' }), ref: 'no-such-ref-zzz', strict: 'true',
    expect_ok: true, expect_degraded: true, expect_source: 'bundled_fallback', expect_sha: false, expect_missing: [], expect_unused: [] },
  { case_id: 'P06-undeclared-variable-flagged', prompt_id: 'rag/answerer', variables: JSON.stringify({ question: 'q', context_block: 'c', min_citations: '2', nonsense: 'z' }), ref: 'main', strict: 'true',
    expect_ok: true, expect_degraded: false, expect_source: 'github', expect_sha: true, expect_missing: [], expect_unused: ['nonsense'] },
  { case_id: 'P07-malformed-variables-json', prompt_id: 'rag/answerer', variables: '{not json', ref: 'main', strict: 'false',
    expect_ok: true, expect_degraded: false, expect_source: 'github', expect_sha: true, expect_missing: ['question', 'context_block', 'min_citations'], expect_unused: [] }
];
return F.map(function (f) { return { json: f }; });

const r = ($json && $json.json) ? $json.json : $json;
return { json: {
  source_workflow: r.source_workflow, ok: r.ok, degraded: r.degraded, source: r.source,
  has_sha: !!r.sha, version: r.version, prompt_chars: r.prompt ? String(r.prompt).length : 0,
  missing_variables: r.missing_variables || [], unused_variables: r.unused_variables || [],
  issues: r.issues || [], latency_ms: r.latency_ms, provenance: r.provenance
} };

const fixtures = $('Build Prompt Fixtures').all().map(function (i) { return i.json; });
const results = $input.all().map(function (i) { return i.json; });

function hasAll(actual, expected) {
  return expected.every(function (e) { return (actual || []).indexOf(e) !== -1; });
}

const rows = results.map(function (r, idx) {
  const fx = fixtures[idx] || {};
  const fails = [];
  if (r.ok !== fx.expect_ok) { fails.push('expected ok=' + fx.expect_ok + ' got ' + r.ok); }
  if (r.degraded !== fx.expect_degraded) { fails.push('expected degraded=' + fx.expect_degraded + ' got ' + r.degraded); }
  if (r.source !== fx.expect_source) { fails.push('expected source=' + fx.expect_source + ' got ' + r.source); }
  if (r.has_sha !== fx.expect_sha) { fails.push('expected sha present=' + fx.expect_sha + ' got ' + r.has_sha); }
  if (!hasAll(r.missing_variables, fx.expect_missing || [])) { fails.push('missing_variables did not contain ' + (fx.expect_missing || []).join(',')); }
  if (!hasAll(r.unused_variables, fx.expect_unused || [])) { fails.push('unused_variables did not contain ' + (fx.expect_unused || []).join(',')); }
  return {
    case_id: fx.case_id, pass: fails.length === 0,
    ok: r.ok, degraded: r.degraded, source: r.source, has_sha: r.has_sha,
    prompt_version: r.version, prompt_chars: r.prompt_chars,
    missing_variables: r.missing_variables, unused_variables: r.unused_variables,
    issues: r.issues, fail_reasons: fails, latency_ms_measured: r.latency_ms, provenance: r.provenance
  };
});
const passed = rows.filter(function (r) { return r.pass; }).length;
const lats = rows.map(function (r) { return r.latency_ms_measured; }).filter(function (v) { return typeof v === 'number'; }).sort(function (a, b) { return a - b; });
return [{ json: {
  suite: 'prompt-registry-fixtures-v1', generated_at: new Date().toISOString(), n8n_execution_id: $execution.id,
  note: 'Fetches the real prompts/ directory from GitHub over the anonymous Contents API. latency_ms_measured includes the GitHub round trip.',
  total: rows.length, passed: passed, failed: rows.length - passed, all_passed: passed === rows.length,
  latency_ms_p50_measured: lats.length ? lats[Math.max(0, Math.ceil(0.5 * lats.length) - 1)] : null,
  latency_ms_max_measured: lats.length ? lats[lats.length - 1] : null,
  cases: rows
} }];
